import React, { useEffect, useState } from "react";

const AuthGuard = ({ children }) => {
  const [isChecking, setIsChecking] = useState(true);
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Check if we're in the process of logging out
    const isLoggingOut = sessionStorage.getItem("isLoggingOut");
    if (isLoggingOut) {
      // Clear the flag and show loading message briefly
      sessionStorage.removeItem("isLoggingOut");
      return;
    }

    const checkAuth = async () => {
      try {
        const response = await fetch("http://localhost:3002/me", { credentials: "include" });
        
        if (!response.ok) {
          console.log("Not authenticated, redirecting to signup");
          // Give time for redirect to register in browser
          setTimeout(() => {
            // Try frontend first, fallback to dashboard signup
            fetch("http://localhost:3000/signup", { credentials: "include", method: "HEAD" })
              .then(() => {
                window.location.href = "http://localhost:3000/signup";
              })
              .catch(() => {
                // If frontend not available, stay and show message
                window.location.href = "/";
              });
          }, 100);
          return;
        }

        const data = await response.json();
        if (data && data.user) {
          setUser(data.user);
          setIsChecking(false);
        } else {
          setTimeout(() => {
            window.location.href = "http://localhost:3000/signup";
          }, 100);
        }
      } catch (error) {
        console.error("Auth check failed:", error);
        setTimeout(() => {
          window.location.href = "http://localhost:3000/signup";
        }, 100);
      }
    };

    checkAuth();
  }, []);

  if (isChecking) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        fontSize: "18px"
      }}>
        <p>Checking your account...</p>
      </div>
    );
  }

  return React.Children.map(children, (child) =>
    React.cloneElement(child, { user })
  );
};

export default AuthGuard;
